int
fd_ed25519_verify( uchar const msg[], /* msg_sz */
                   ulong msg_sz,
                   uchar const sig[ 64 ],
                   uchar const public_key[ 32 ],
                   fd_sha512_t * sha ) {
  int ok = 1;
  int err = crc_adx_verify_core( msg, msg_sz, sig, public_key, sha, NULL, &ok, NULL );
  if( FD_UNLIKELY( err ) ) return err;
  return FD_LIKELY( ok ) ? FD_ED25519_SUCCESS : FD_ED25519_ERR_MSG;
}

void
fd_ed25519_verify_batch_multi_msg( uchar const * const msgs[],
                                   ulong const msg_szs[],
                                   uchar const * const sigs[],
                                   uchar const * const public_keys[],
                                   fd_sha512_t * shas[],
                                   int results[],
                                   ulong batch_sz ) {
  for( ulong j=0; j<batch_sz; j++ ) results[j] = fd_ed25519_verify( msgs[j], msg_szs[j], sigs[j], public_keys[j], shas[j] );
}

/* the transaction verdict from per-signature codes: the first that is neither SUCCESS nor
   ERR_MSG, else ERR_MSG when any equation failed, else SUCCESS */
int
crc_adx_verdict( int const codes[], ulong n ) {
  int ok = 1;
  for( ulong j=0; j<n; j++ ) {
    if( FD_LIKELY( codes[j]==FD_ED25519_SUCCESS ) ) continue;
    if( codes[j]!=FD_ED25519_ERR_MSG ) return codes[j];
    ok = 0;
  }
  return FD_LIKELY( ok ) ? FD_ED25519_SUCCESS : FD_ED25519_ERR_MSG;
}

int
fd_ed25519_verify_batch_single_msg( uchar const msg[], /* msg_sz */
                                    ulong const msg_sz,
                                    uchar const signatures[ 64 ], /* 64 * batch_sz */
                                    uchar const pubkeys[ 32 ], /* 32 * batch_sz */
                                    fd_sha512_t * shas[ 1 ], /* batch_sz */
                                    uchar const batch_sz ) {
  if( FD_UNLIKELY( batch_sz == 0 || batch_sz > 16 ) ) return FD_ED25519_ERR_SIG;
  uchar const * msgs[16], * sigs[16], * pks[16]; ulong szs[16]; int codes[16];
  for( ulong j=0; j<batch_sz; j++ ) { msgs[j] = msg; szs[j] = msg_sz; sigs[j] = signatures+64UL*j; pks[j] = pubkeys+32UL*j; }
  fd_ed25519_verify_batch_multi_msg( msgs, szs, sigs, pks, shas, codes, batch_sz );
  return crc_adx_verdict( codes, batch_sz );
}
